INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'After the wings have baked for 15 mins, remove from oven and drain off any accumulated fat.' FROM recipes WHERE external_source_id = '81666' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, 'Pour the sauce over the wings and return to oven.' FROM recipes WHERE external_source_id = '81666' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'Bake for 20 more minutes, turning wings over in sauce frequently (I do it every 4 or 5 minutes), so that they are thoroughly coated.' FROM recipes WHERE external_source_id = '81666' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 9, 'Wings should be well glazed and sticky when done.' FROM recipes WHERE external_source_id = '81666' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'Prepare grill or heat broiler.' FROM recipes WHERE external_source_id = '84076' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Combine sugar, vinegar, cumin and red pepper in a small bowl; mix well.' FROM recipes WHERE external_source_id = '84076' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Put pork chops in a large plastic food storage bag and pour cumin mixture over; turn meat to coat; seal bag and marinate in the fridge for at least 10 minutes, or as long as 6 hours.' FROM recipes WHERE external_source_id = '84076' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Remove meat from marinade; grill or broil, turning once, until cooked through, 8-10 minutes.' FROM recipes WHERE external_source_id = '84076' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'Move to a cooler part of the grill if the sugar in the rub starts to burn.' FROM recipes WHERE external_source_id = '84076' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 1, 'To cook trout, wash and dry the fish inside and out and coat sides with a little olive oil.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 2, 'Slice mushrooms and place half in the bottom of a shallow baking dish.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 3, 'Salt and pepper fish, inside and out, to taste and place in dish on top of mushrooms.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 4, 'Sprinkle bread crumbs over fish along with the minced parsley, chopped garlic and the green onion.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 5, 'If using fresh lemons, squeeze 1 or 2 directly over the entire trout including the inside.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 6, 'Meanwhile melt butter, add to olive oil and the juice of 2 lemons.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 7, 'Pour slowly over fish saving about half of the mixture.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 8, 'Bake for 20-25 minutes at 375 degrees or until they are tender and bread crumbs are light brown.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 9, 'Fish is done when the meat flakes easily when a fork is inserted into the flesh and lifted up slightly.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 10, 'Just before the fish are done, saute 1-2 minutes , the remaining mushrooms in the sauce that is left and pour over top after placing trout on a serving plate.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 11, 'Garnish with a few lemon wedges and a few sprigs of fresh parsley.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
INSERT INTO recipe_steps (recipe_id, step_number, instruction) SELECT recipe_id, 12, 'Serve this Italian Trout recipe with rice, or Italian pasta, and a vegetable.' FROM recipes WHERE external_source_id = '10852' ON CONFLICT (recipe_id, step_number) DO NOTHING;
